insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('4be9ac65-7a89-5548-bc5d-534c47e036f0', 'hiw-0001', 'e7e460f5-1b15-58aa-b20e-48cb17d9bd6d', 'beginner', 'Read the text while you listen. Click each word that is different from what the speaker says.', '{"audio_script": "Our class visited the science museum on Thursday and saw a large model of the planets.", "transcript": "Our class visited the history museum on Thursday and saw a small model of the planets."}'::jsonb, '{"incorrect_words": [{"index": 4, "word": "history", "spoken": "science"}, {"index": 11, "word": "small", "spoken": "large"}]}'::jsonb, 'The speaker said "science" and "large".', 'Follow a transcript while listening.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('53c94e83-dfa7-538a-bff2-1960096b9d04', 'hiw-0002', 'e7e460f5-1b15-58aa-b20e-48cb17d9bd6d', 'intermediate', 'Read the text while you listen. Click each word that is different from what the speaker says.', '{"audio_script": "The survey found that most employees preferred flexible hours to a higher salary.", "transcript": "The survey showed that most employees preferred flexible days to a higher salary."}'::jsonb, '{"incorrect_words": [{"index": 2, "word": "showed", "spoken": "found"}, {"index": 8, "word": "days", "spoken": "hours"}]}'::jsonb, 'The speaker said "found" and "hours".', 'Notice small changes in meaning.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3bc936f4-8162-5200-bb45-24a66e81027e', 'wfd-0001', 'c4f6e94e-f068-5719-b756-005c6e22e8fa', 'beginner', 'Listen to the sentence. Type it exactly as you hear it.', '{"audio_script": "The lecture will start in the main hall."}'::jsonb, '{"reference_text": "The lecture will start in the main hall."}'::jsonb, 'Write every word, and check small words like "the" and "in".', 'Write a short sentence accurately.', array['Listening', 'Writing']::text[], '{}'::text[], 'published');
