insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('e2a4c324-a4e4-5d37-a5be-ae4dcfbcc418', 'lmcs-0003', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'beginner', 'Listen, then choose the one answer that matches what the speaker says.', '{"audio_script": "Good morning, everyone. The school trip to the science centre is on Friday. The bus leaves at half past eight, so please arrive by twenty past. Bring a packed lunch and a notebook. We''ll be back at school by three.", "question": "What time does the bus leave?"}'::jsonb, '{"correct": ["C"]}'::jsonb, '"The bus leaves at half past eight". 8:20 is the time to arrive.', 'Catch a key detail in a short talk.', array['Listening']::text[], '{}'::text[], 'published');
