insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('7fd9440e-3ed8-5f6c-a264-48ea7924c955', 'hiw-0003', 'e7e460f5-1b15-58aa-b20e-48cb17d9bd6d', 'beginner', 'Read the text while you listen. Click each word that is different from what the speaker says.', '{"audio_script": "I usually walk to work, but today I took the train because it was raining.", "transcript": "I usually drive to work, but today I took the bus because it was raining."}'::jsonb, '{"incorrect_words": [{"index": 2, "word": "drive", "spoken": "walk"}, {"index": 10, "word": "bus", "spoken": "train"}]}'::jsonb, 'The speaker said "walk" and "train".', 'Follow a transcript while listening.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
