insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('9f30aef1-20fe-52e9-a134-6a5bf3f9e0f6', 'lmcs-0004', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'beginner', 'Listen, then choose the one answer that matches what the speaker says.', '{"audio_script": "If you want to join the swimming club, you need to fill in a form at reception. The club meets on Tuesday and Thursday evenings. New members get their first two weeks free, and after that it costs ten pounds a month.", "question": "How much does the club cost after the first two weeks?"}'::jsonb, '{"correct": ["C"]}'::jsonb, '"after that it costs ten pounds a month".', 'Catch a key detail in a short talk.', array['Listening']::text[], '{}'::text[], 'published');
