insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('bf9fe872-00b8-5b5d-b429-891eafc9506e', 'hcs-0012', '3240907f-f6da-5d0f-ae2b-59990a282e5f', 'intermediate', 'Listen, then choose the summary that matches the talk best.', '{"audio_script": "Our café is introducing a new loyalty card next week. Every time you buy a hot drink, we''ll stamp your card. After nine stamps, your tenth drink is free. The cards are available at the counter, and you don''t need to give us any personal details."}'::jsonb, '{"correct": ["A"]}'::jsonb, 'The right summary explains how the card works.', 'Choose the summary that includes all main points.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
