insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('fa4b99dc-e2b8-5e26-93bb-3fe233fc635d', 'hiw-0012', 'e7e460f5-1b15-58aa-b20e-48cb17d9bd6d', 'intermediate', 'Read the text while you listen. Click each word that is different from what the speaker says.', '{"audio_script": "My flight was delayed by two hours, so I missed the start of the meeting.", "transcript": "My flight was delayed by three hours, so I missed the end of the meeting."}'::jsonb, '{"incorrect_words": [{"index": 5, "word": "three", "spoken": "two"}, {"index": 11, "word": "end", "spoken": "start"}]}'::jsonb, 'The speaker said "two" and "start".', 'Follow a transcript while listening.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
