insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('889b74df-f0a7-5509-a8e0-c93976adcdac', 'lmcs-0013', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'advanced', 'Listen, then choose the one answer that matches what the speaker says.', '{"audio_script": "Our research team compared two groups of students learning vocabulary. The first group studied a list once for an hour. The second group studied the same list for four short sessions spread over a week. A month later, the second group remembered almost twice as many words. This supports the idea that spacing out practice is more effective than cramming.", "question": "Which group remembered more words?"}'::jsonb, '{"correct": ["C"]}'::jsonb, 'The second group, which spread its study over a week, remembered almost twice as many words.', 'Catch a key detail in a short talk.', array['Listening']::text[], '{}'::text[], 'published');
