insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('0b87f073-b996-5907-bae0-9daa10fb5267', '889b74df-f0a7-5509-a8e0-c93976adcdac', 'C', 'The group that studied in short sessions over a week', true, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('9c55dcba-adca-5990-a270-0996d6458920', 'lmcm-0013', '98cdddc4-46fd-53a3-aa5d-862c3528a2fe', 'advanced', 'Listen, then choose every answer that matches what the speaker says. There is more than one.', '{"audio_script": "Our research team compared two groups of students learning vocabulary. The first group studied a list once for an hour. The second group studied the same list for four short sessions spread over a week. A month later, the second group remembered almost twice as many words. This supports the idea that spacing out practice is more effective than cramming.", "question": "Which details are part of the study?"}'::jsonb, '{"correct": ["B", "C", "D"]}'::jsonb, 'The groups used the same list, not different textbooks.', 'Track which ideas the speaker states.', array['Listening']::text[], '{}'::text[], 'published');
