insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('9f2302f5-96f7-5d34-a115-19afbf45698d', '9c55dcba-adca-5990-a270-0996d6458920', 'D', 'Memory was tested a month later.', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('34dfa7f8-fe08-5741-9578-d383385385cb', 'hcs-0013', '3240907f-f6da-5d0f-ae2b-59990a282e5f', 'advanced', 'Listen, then choose the summary that matches the talk best.', '{"audio_script": "Our research team compared two groups of students learning vocabulary. The first group studied a list once for an hour. The second group studied the same list for four short sessions spread over a week. A month later, the second group remembered almost twice as many words. This supports the idea that spacing out practice is more effective than cramming."}'::jsonb, '{"correct": ["A"]}'::jsonb, 'The right summary gives the method and the finding.', 'Choose the summary that includes all main points.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
