insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('e0f631bb-d2ac-5cbe-8ea7-acfe3180b1d9', 'lmcs-0019', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'advanced', 'Listen, then choose the one answer that matches what the speaker says.', '{"audio_script": "In this talk, I want to challenge the idea that creativity is a rare gift. Studies of successful artists and inventors show that they produced a large number of works, most of which were not remarkable. Their famous achievements came from this high volume of attempts. So rather than waiting for inspiration, we should encourage regular practice and accept that many attempts will fail.", "question": "What is the speaker''s main argument?"}'::jsonb, '{"correct": ["B"]}'::jsonb, 'The speaker argues that famous achievements came from "this high volume of attempts".', 'Catch a key detail in a short talk.', array['Listening']::text[], '{}'::text[], 'published');
