insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('995261b3-a779-56a0-bc23-7dc4cb9ddb3d', 'e0f631bb-d2ac-5cbe-8ea7-acfe3180b1d9', 'C', 'Most inventors produced only a few works.', false, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('79fd752e-d216-53a0-8394-65e769907227', 'lmcm-0019', '98cdddc4-46fd-53a3-aa5d-862c3528a2fe', 'advanced', 'Listen, then choose every answer that matches what the speaker says. There is more than one.', '{"audio_script": "In this talk, I want to challenge the idea that creativity is a rare gift. Studies of successful artists and inventors show that they produced a large number of works, most of which were not remarkable. Their famous achievements came from this high volume of attempts. So rather than waiting for inspiration, we should encourage regular practice and accept that many attempts will fail.", "question": "Which points does the speaker make?"}'::jsonb, '{"correct": ["A", "B", "C"]}'::jsonb, 'The speaker says we should not wait for inspiration.', 'Track which ideas the speaker states.', array['Listening']::text[], '{}'::text[], 'published');
