insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('dae19d8c-d103-599a-bd62-2439cd10af30', '79fd752e-d216-53a0-8394-65e769907227', 'C', 'We should accept that many attempts fail.', true, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('fb4876b4-b71c-5646-a1c1-04936fb9bbb9', '79fd752e-d216-53a0-8394-65e769907227', 'D', 'Inspiration is the key to success.', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3793b80f-76bd-5811-82b5-a1a771ec8d15', 'hcs-0019', '3240907f-f6da-5d0f-ae2b-59990a282e5f', 'advanced', 'Listen, then choose the summary that matches the talk best.', '{"audio_script": "In this talk, I want to challenge the idea that creativity is a rare gift. Studies of successful artists and inventors show that they produced a large number of works, most of which were not remarkable. Their famous achievements came from this high volume of attempts. So rather than waiting for inspiration, we should encourage regular practice and accept that many attempts will fail."}'::jsonb, '{"correct": ["A"]}'::jsonb, 'The right summary captures the argument and its conclusion.', 'Choose the summary that includes all main points.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('8896db0f-6685-5c3c-9fcc-f2d15783c27a', '3793b80f-76bd-5811-82b5-a1a771ec8d15', 'A', 'Creative success is linked to producing many works, so regular practice and accepting failure matter more than waiting for inspiration.', true, 1);
