insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('af497915-9617-53d7-852a-c56b04264be5', 'lmcs-0022', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'advanced', 'Listen, then choose the one answer that matches what the speaker says.', '{"audio_script": "Today I''ll discuss why some cities succeed in reducing car use. The key seems to be a combination of measures rather than a single policy. Cities that improved public transport, made cycling safer and charged drivers to enter the centre saw the biggest changes. Those that introduced only one of these measures saw much smaller effects.", "question": "What does the speaker say is the key to reducing car use?"}'::jsonb, '{"correct": ["B"]}'::jsonb, '"The key seems to be a combination of measures rather than a single policy".', 'Catch a key detail in a short talk.', array['Listening']::text[], '{}'::text[], 'published');
