insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ec374180-89f4-52cd-9237-7d67ef633c69', 'hcs-0022', '3240907f-f6da-5d0f-ae2b-59990a282e5f', 'advanced', 'Listen, then choose the summary that matches the talk best.', '{"audio_script": "Today I''ll discuss why some cities succeed in reducing car use. The key seems to be a combination of measures rather than a single policy. Cities that improved public transport, made cycling safer and charged drivers to enter the centre saw the biggest changes. Those that introduced only one of these measures saw much smaller effects."}'::jsonb, '{"correct": ["C"]}'::jsonb, 'The right summary states the main finding about combined measures.', 'Choose the summary that includes all main points.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
