insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('679d9b83-4182-5d89-9d5e-c81ea9217719', 'lmcs-0026', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'advanced', 'Listen, then choose the one answer that matches what the speaker says.', '{"audio_script": "Good morning. I''d like to talk about the role of sleep in learning. While we sleep, the brain replays experiences from the day and strengthens important memories. In one experiment, students who slept after learning a task performed better the next day than students who stayed awake for the same length of time. So staying up all night to study may actually work against you.", "question": "What happened in the experiment?"}'::jsonb, '{"correct": ["B"]}'::jsonb, 'Students who slept "performed better the next day".', 'Catch a key detail in a short talk.', array['Listening']::text[], '{}'::text[], 'published');
