insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('1c7cf82d-5bc9-5ef2-8fcf-3b617bd411b1', 'hcs-0026', '3240907f-f6da-5d0f-ae2b-59990a282e5f', 'advanced', 'Listen, then choose the summary that matches the talk best.', '{"audio_script": "Good morning. I''d like to talk about the role of sleep in learning. While we sleep, the brain replays experiences from the day and strengthens important memories. In one experiment, students who slept after learning a task performed better the next day than students who stayed awake for the same length of time. So staying up all night to study may actually work against you."}'::jsonb, '{"correct": ["A"]}'::jsonb, 'The right summary gives the main finding and the advice.', 'Choose the summary that includes all main points.', array['Listening', 'Reading']::text[], '{}'::text[], 'published');
