insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('f2cd9ba3-4763-56c1-9977-4c079e300b3b', 'lmcs-0029', 'b3e2cddb-71ff-51d4-bf6f-d531426d9e54', 'advanced', 'Listen, then choose the one answer that matches what the speaker says.', '{"audio_script": "In this talk I''ll compare two approaches to protecting coastlines. Hard defences, such as sea walls, can stop waves effectively but are expensive and may increase erosion further along the coast. Soft approaches, such as restoring sand dunes and salt marshes, absorb wave energy more naturally and provide habitats for wildlife, though they need space and time to become established.", "question": "What is one drawback of sea walls mentioned by the speaker?"}'::jsonb, '{"correct": ["C"]}'::jsonb, 'They "may increase erosion further along the coast".', 'Catch a key detail in a short talk.', array['Listening']::text[], '{}'::text[], 'published');
