insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('8f36e9b0-b124-5278-9b90-79783a14a631', 'f2cd9ba3-4763-56c1-9977-4c079e300b3b', 'C', 'They may increase erosion elsewhere.', true, 3);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('9299f0b6-abc5-51ad-bf78-0207f425d459', 'lmcm-0029', '98cdddc4-46fd-53a3-aa5d-862c3528a2fe', 'advanced', 'Listen, then choose every answer that matches what the speaker says. There is more than one.', '{"audio_script": "In this talk I''ll compare two approaches to protecting coastlines. Hard defences, such as sea walls, can stop waves effectively but are expensive and may increase erosion further along the coast. Soft approaches, such as restoring sand dunes and salt marshes, absorb wave energy more naturally and provide habitats for wildlife, though they need space and time to become established.", "question": "Which advantages of soft approaches does the speaker mention?"}'::jsonb, '{"correct": ["A", "C"]}'::jsonb, 'They "need space and time".', 'Track which ideas the speaker states.', array['Listening']::text[], '{}'::text[], 'published');
