insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('1d4e64b8-a8b4-541f-a664-72bc638d4df0', 'd304e691-9a50-50c6-8b48-bae9aad07874', 'D', 'Free computer classes', true, 4);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e7ee6a7f-ab1a-536b-9a41-d8314c58caf7', 'd304e691-9a50-50c6-8b48-bae9aad07874', 'E', 'A quiet study room', true, 5);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('fb889ed0-fac4-5901-bff3-bb757ced9975', 'rop-0003', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Maria practised the recipe at home the next weekend."}, {"id": "p2", "text": "Maria wanted to learn to cook, so she joined an evening class."}, {"id": "p3", "text": "Her family liked it so much that she now cooks pasta every Sunday."}, {"id": "p4", "text": "At the first lesson, the teacher showed the group how to make fresh pasta."}]}'::jsonb, '{"order": ["p2", "p4", "p1", "p3"]}'::jsonb, 'The first sentence introduces Maria and her goal. Then come the first lesson, the practice at home and the result.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('08545cf3-95eb-59a0-b77d-438c4bffae0a', 'rwfib-0003', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "Many people {{1}} to shop online because it saves time. However, some still {{2}} visiting real shops at the weekend.", "blanks": {"1": ["preferring", "prefers", "prefer"], "2": ["enjoy", "enjoys", "enjoyed"]}}'::jsonb, '{"blanks": {"1": "prefer", "2": "enjoy"}}'::jsonb, 'After "Many people" (plural, present simple) we need "prefer". After "some still" in the present simple we need "enjoy".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('47820896-3ec8-515a-a3b2-f3490d899069', 'rfib-0003', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Drinking enough water helps your body {{1}} well. Doctors often {{2}} adults to drink several glasses a day.", "word_bank": ["advise", "work", "forget", "eat"]}'::jsonb, '{"blanks": {"1": "work", "2": "advise"}}'::jsonb, 'Your body "works" well; doctors "advise" people to do something. "eat" and "forget" do not fit the meaning.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('70780c39-91fb-5c30-ad95-96910f1685cd', 'rmcs-0004', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Scientists say that most adults need between seven and nine hours of sleep each night. People who sleep too little often find it hard to concentrate, and they may catch colds more easily. Using phones late at night can make it harder to fall asleep, because the bright screen tells the brain that it is still daytime.", "question": "According to the text, why can phones make it harder to fall asleep?"}'::jsonb, '{"correct": ["D"]}'::jsonb, 'The text says the bright screen "tells the brain that it is still daytime".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
