insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('a009653c-aa4b-5bc3-88b8-8887c0bd8383', '70780c39-91fb-5c30-ad95-96910f1685cd', 'B', 'They make people catch colds.', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('6cccaf66-d565-5ca8-a45b-adf2d14ce3f5', '70780c39-91fb-5c30-ad95-96910f1685cd', 'C', 'People use them to set alarms.', false, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e29528a0-87f5-5c6c-8ebc-1e6f014fbfd8', '70780c39-91fb-5c30-ad95-96910f1685cd', 'D', 'The bright screen makes the brain think it is day.', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3d25c815-43ae-5ce3-8f35-6baac556e146', 'rmcm-0004', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'beginner', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Scientists say that most adults need between seven and nine hours of sleep each night. People who sleep too little often find it hard to concentrate, and they may catch colds more easily. Using phones late at night can make it harder to fall asleep, because the bright screen tells the brain that it is still daytime.", "question": "What problems does the text link with too little sleep?"}'::jsonb, '{"correct": ["B", "D"]}'::jsonb, 'The text mentions concentration and colds. Weight and eyesight are not mentioned.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('dc6f00ef-e7ad-5700-97a4-6a85aa792019', '3d25c815-43ae-5ce3-8f35-6baac556e146', 'A', 'Poor eyesight', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('3792ad0a-9b7f-5d9a-aa36-59261e417faf', '3d25c815-43ae-5ce3-8f35-6baac556e146', 'B', 'Catching colds more easily', true, 2);
