insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('abbd5900-709e-50c4-8a30-5e4c09a79ffd', '3d25c815-43ae-5ce3-8f35-6baac556e146', 'D', 'Difficulty concentrating', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3f8b9a67-ba0b-55ad-8bb6-b547c9c46681', 'rop-0004', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Our town has a new bicycle scheme."}, {"id": "p2", "text": "After using it, they simply return it to any station."}, {"id": "p3", "text": "Since the scheme started, traffic in the centre has fallen noticeably."}, {"id": "p4", "text": "Anyone can borrow a bike from one of twenty stations in the centre."}]}'::jsonb, '{"order": ["p1", "p4", "p2", "p3"]}'::jsonb, 'Start with the topic (the scheme), then how to borrow, how to return, and finally the result.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('7a5068f2-413b-59c7-9f04-30f840e37b81', 'rwfib-0004', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "The concert was {{1}} because the singer was ill. Fans who had bought tickets were {{2}} their money back.", "blanks": {"1": ["cancel", "cancelling", "cancelled"], "2": ["offering", "offer", "offered"]}}'::jsonb, '{"blanks": {"1": "cancelled", "2": "offered"}}'::jsonb, 'Both gaps need the passive: "was cancelled" and "were offered".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('57dc25b1-4523-54bb-92e2-025de10bc904', 'rfib-0004', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Learning a new language takes {{1}}. It is better to study a little every day than to {{2}} for many hours once a week.", "word_bank": ["money", "patience", "hurry", "study"]}'::jsonb, '{"blanks": {"1": "patience", "2": "study"}}'::jsonb, 'Learning a language "takes patience"; the sentence compares two ways to study. "hurry" and "money" do not fit.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('69bafee3-3f7a-5bfc-a674-7f889d9254d6', 'rmcs-0005', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Bees are important for growing food. When they move from flower to flower, they carry pollen, which plants need to make fruit and seeds. In many countries the number of bees has fallen, partly because of chemicals used on farms and partly because there are fewer wild flowers. Some cities now encourage people to plant flowers on balconies and in gardens to help.", "question": "What is the main idea of the text?"}'::jsonb, '{"correct": ["C"]}'::jsonb, 'The text explains why bees matter and why their numbers have fallen; the other answers are not stated.', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
