insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('01ab6c6b-09a6-583f-b052-e88dfaf7b0d2', 'rmcm-0005', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Bees are important for growing food. When they move from flower to flower, they carry pollen, which plants need to make fruit and seeds. In many countries the number of bees has fallen, partly because of chemicals used on farms and partly because there are fewer wild flowers. Some cities now encourage people to plant flowers on balconies and in gardens to help.", "question": "Which reasons for the fall in bee numbers does the text give?"}'::jsonb, '{"correct": ["B", "D"]}'::jsonb, 'The text says "partly because of chemicals ... and partly because there are fewer wild flowers".', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
