insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('92886c11-2de3-5475-a1e3-2822535922f3', '01ab6c6b-09a6-583f-b052-e88dfaf7b0d2', 'D', 'Fewer wild flowers', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('57a3c2dc-a5b5-515f-ab8c-194ca52e440c', 'rop-0005', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "First, every classroom got three bins: one for paper, one for plastic and one for other waste."}, {"id": "p2", "text": "Then a group of students checked the bins every Friday and recorded the results."}, {"id": "p3", "text": "By the end of the year, the school was throwing away half as much rubbish as before."}, {"id": "p4", "text": "Last year our school started a recycling project."}]}'::jsonb, '{"order": ["p4", "p1", "p2", "p3"]}'::jsonb, 'Topic first, then the steps (First, Then) and the result (By the end of the year).', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ce6c96a3-df04-5beb-b9a4-287626a3d131', 'rwfib-0005', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "Although the weather was {{1}}, the football match went ahead. The players were tired but {{2}} with the result.", "blanks": {"1": ["terribly", "terror", "terrible"], "2": ["please", "pleased", "pleasing"]}}'::jsonb, '{"blanks": {"1": "terrible", "2": "pleased"}}'::jsonb, '"was" is followed by an adjective: "terrible". People feel "pleased" (-ed adjective for feelings).', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('f3439d7c-dff1-5ec1-a919-3805f08d864d', 'rfib-0005', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "The hotel is in a {{1}} street, but it is only a short {{2}} from the main square.", "word_bank": ["busy", "quiet", "loud", "walk", "drive"]}'::jsonb, '{"blanks": {"1": "quiet", "2": "walk"}}'::jsonb, '"but" shows a contrast: the street is quiet, yet the square is a short walk away.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('066ca572-2f77-5689-9b94-57bee3552fe2', 'rmcs-0006', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "More people now work from home for at least part of the week. Many say they save time and money because they do not travel to an office. However, some workers feel lonely, and managers worry that it is harder to share ideas. For this reason, many companies now use a mixed model, with two or three office days each week.", "question": "Why do many companies use a mixed model?"}'::jsonb, '{"correct": ["B"]}'::jsonb, 'The text gives benefits (time, money) and problems (loneliness, sharing ideas), then says "For this reason" companies mix the two.', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
