insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('701dd6e6-dd77-5cc6-9edc-680552e6b2d3', '066ca572-2f77-5689-9b94-57bee3552fe2', 'B', 'Home working has both benefits and problems.', true, 2);
