insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('0c8bfa48-867d-5f12-b454-0539132ced1f', '066ca572-2f77-5689-9b94-57bee3552fe2', 'D', 'Managers prefer to work from home.', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('8ab37b08-b775-593a-a914-5d489355f9e8', 'rmcm-0006', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "More people now work from home for at least part of the week. Many say they save time and money because they do not travel to an office. However, some workers feel lonely, and managers worry that it is harder to share ideas. For this reason, many companies now use a mixed model, with two or three office days each week.", "question": "Which problems with working from home does the text mention?"}'::jsonb, '{"correct": ["A", "C"]}'::jsonb, 'Loneliness and sharing ideas are mentioned. Workers actually save on travel.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
