insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('7dc387e3-ef01-5e3d-a561-251e2e6f0fbf', '8ab37b08-b775-593a-a914-5d489355f9e8', 'D', 'Workers spend more on travel.', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('bbfe63f5-494f-56df-95d2-bbf4653f42aa', 'rop-0006', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Paper was first made in China about two thousand years ago."}, {"id": "p2", "text": "From there, it reached Europe, where the first paper mills opened in Spain."}, {"id": "p3", "text": "Over many centuries, the method spread along trade routes to the Middle East."}, {"id": "p4", "text": "Later, the printing press made paper even more important across the world."}]}'::jsonb, '{"order": ["p1", "p3", "p2", "p4"]}'::jsonb, 'The text follows time and place: China, then the Middle East, then Europe, then later the printing press.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('a6478d3d-b2a0-5c7f-bb53-bf214516e742', 'rwfib-0006', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "The new park is {{1}} with families. On sunny days it can get quite {{2}}.", "blanks": {"1": ["popularly", "popularity", "popular"], "2": ["crowded", "crowd", "crowding"]}}'::jsonb, '{"blanks": {"1": "popular", "2": "crowded"}}'::jsonb, '"is" + adjective: "popular". "get" + adjective: "crowded".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('6e987b48-3c7a-5a6d-929b-bb2dad9467b9', 'rfib-0006', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Before you sign a contract, read it {{1}}. If you do not understand something, ask for an {{2}}.", "word_bank": ["carefully", "invitation", "explanation", "quickly"]}'::jsonb, '{"blanks": {"1": "carefully", "2": "explanation"}}'::jsonb, 'You read a contract carefully and ask for an explanation of something you do not understand.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('79414da9-63b6-56ee-bd2e-f8270335326e', 'rmcs-0007', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Every year millions of tonnes of plastic end up in the sea. Large pieces can trap birds and fish, while tiny pieces, called microplastics, are eaten by sea animals and can enter the food chain. Some countries have banned plastic bags, and research shows that these bans quickly reduce the number of bags found on beaches.", "question": "What does the research show about plastic bag bans?"}'::jsonb, '{"correct": ["D"]}'::jsonb, 'The last sentence says the bans "quickly reduce the number of bags found on beaches".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
