insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('182d9b0d-650b-5cb0-b26c-3ab2c43ecb05', '79414da9-63b6-56ee-bd2e-f8270335326e', 'C', 'They are only used in a few cities.', false, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('bab1b432-31c9-5540-9ea3-2e0b1eef8794', '79414da9-63b6-56ee-bd2e-f8270335326e', 'D', 'They quickly reduce the number of bags on beaches.', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('f7a669f6-6dcd-5e4f-aa25-9c3b78aa6f2e', 'rmcm-0007', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Every year millions of tonnes of plastic end up in the sea. Large pieces can trap birds and fish, while tiny pieces, called microplastics, are eaten by sea animals and can enter the food chain. Some countries have banned plastic bags, and research shows that these bans quickly reduce the number of bags found on beaches.", "question": "How does plastic harm sea life, according to the text?"}'::jsonb, '{"correct": ["A", "B"]}'::jsonb, 'Trapping and eating microplastics are mentioned. Temperature and sunlight are not.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
