insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('919f0d14-c9d1-5e65-8712-2b8808e8a63e', 'f7a669f6-6dcd-5e4f-aa25-9c3b78aa6f2e', 'C', 'It makes the water warmer.', false, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e82b5d49-3753-53ca-a20d-3ebe8baf6998', 'f7a669f6-6dcd-5e4f-aa25-9c3b78aa6f2e', 'D', 'It blocks sunlight from the seabed.', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('52878e5a-9676-5069-9772-1e7559441840', 'rop-0007', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "However, a desert is really defined by how little rain it gets, not by its temperature."}, {"id": "p2", "text": "This means that some very cold places count as deserts too."}, {"id": "p3", "text": "Most people think of deserts as hot places."}, {"id": "p4", "text": "In fact, the largest desert in the world is Antarctica."}]}'::jsonb, '{"order": ["p3", "p1", "p2", "p4"]}'::jsonb, 'A common belief, then "However" corrects it, "This means" follows from it, and "In fact" gives the surprising example.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('fc4d7a1a-a7fe-57cd-ae57-1cf8e5a85309', 'rwfib-0007', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "She has {{1}} in this city since 2015. Before that, she {{2}} in a small village school.", "blanks": {"1": ["live", "living", "lived"], "2": ["worked", "working", "works"]}}'::jsonb, '{"blanks": {"1": "lived", "2": "worked"}}'::jsonb, '"has ... since" needs the present perfect "has lived". "Before that" points to the past simple "worked".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d581a55c-126f-5035-839e-be9ac05db7fd', 'rfib-0007', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "A good night''s sleep can {{1}} your memory. Students who rest well often {{2}} more of what they studied.", "word_bank": ["remember", "damage", "forget", "improve"]}'::jsonb, '{"blanks": {"1": "improve", "2": "remember"}}'::jsonb, 'Sleep improves memory, so rested students remember more.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ed53a910-c726-5350-8fcc-47d034dc7008', 'rmcs-0008', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Volunteering means giving your time to help others without being paid. People volunteer in hospitals, schools, parks and animal shelters. Research suggests that volunteers often feel happier and less stressed. It can also help young people find work, because they learn new skills and meet people who may later offer them a job.", "question": "According to the text, how can volunteering help young people find work?"}'::jsonb, '{"correct": ["D"]}'::jsonb, 'The last sentence: "they learn new skills and meet people who may later offer them a job".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
