insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('463669b9-e54d-5961-8381-e5a484d8fcd0', 'rmcm-0008', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'beginner', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Volunteering means giving your time to help others without being paid. People volunteer in hospitals, schools, parks and animal shelters. Research suggests that volunteers often feel happier and less stressed. It can also help young people find work, because they learn new skills and meet people who may later offer them a job.", "question": "Where does the text say people volunteer?"}'::jsonb, '{"correct": ["A", "B", "C"]}'::jsonb, 'Hospitals, schools, parks and animal shelters are listed. Banks are not.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
