insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('b156d578-7c42-5c48-8d12-b3fb3f977bb7', '463669b9-e54d-5961-8381-e5a484d8fcd0', 'D', 'Banks', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('c8def627-3768-53d0-ad70-c6e25189534c', 'rop-0008', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Finally, let the soup cook for twenty minutes and blend it until smooth."}, {"id": "p2", "text": "Then add the carrots, some stock and a pinch of salt."}, {"id": "p3", "text": "To make a simple vegetable soup, start by chopping an onion and two carrots."}, {"id": "p4", "text": "Next, fry the onion gently in a little oil until it is soft."}]}'::jsonb, '{"order": ["p3", "p4", "p2", "p1"]}'::jsonb, 'Follow the recipe steps: start by, Next, Then, Finally.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('200d1585-e82e-5581-acba-cf294cd4de6f', 'rwfib-0008', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "If it {{1}} tomorrow, we will stay at home. We can {{2}} a film instead.", "blanks": {"1": ["rained", "rains", "raining"], "2": ["watching", "watch", "watched"]}}'::jsonb, '{"blanks": {"1": "rains", "2": "watch"}}'::jsonb, 'First conditional: "If it rains, we will ...". After "can" we use the base verb "watch".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('2ac2b627-dd6d-562b-9edf-2471f91a4335', 'rfib-0008', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "The company is {{1}} for a new manager. Applicants must have at least five years of {{2}}.", "word_bank": ["looking", "holiday", "experience", "sitting"]}'::jsonb, '{"blanks": {"1": "looking", "2": "experience"}}'::jsonb, 'A company is "looking for" a new person. Applicants need "experience".', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('8240482a-2f6c-52d6-8570-164198f91a7c', 'rmcs-0009', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Some companies now hold walking meetings, where colleagues talk while walking outside instead of sitting in a room. Supporters say that walking helps people think more creatively and makes conversations feel more relaxed. However, walking meetings work best for small groups of two or three people, and they are not suitable when people need to look at documents or take detailed notes.", "question": "When are walking meetings NOT suitable, according to the text?"}'::jsonb, '{"correct": ["D"]}'::jsonb, 'The text says they are "not suitable when people need to look at documents or take detailed notes".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
