insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('962f3354-fb88-530e-a400-7b12f179c5af', 'rmcm-0009', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Some companies now hold walking meetings, where colleagues talk while walking outside instead of sitting in a room. Supporters say that walking helps people think more creatively and makes conversations feel more relaxed. However, walking meetings work best for small groups of two or three people, and they are not suitable when people need to look at documents or take detailed notes.", "question": "Which benefits of walking meetings does the text mention?"}'::jsonb, '{"correct": ["B", "D"]}'::jsonb, 'Creativity and relaxed conversation are mentioned. Shorter meetings are not, and notes are harder.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
