insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('db3bb444-88c1-5830-8cea-7e7a8468af28', '962f3354-fb88-530e-a400-7b12f179c5af', 'D', 'More relaxed conversations', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('6a64e132-8d13-5230-8bfe-7eafd1c4ab6f', 'rop-0009', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "On the day, he was still nervous, but the presentation went very well."}, {"id": "p2", "text": "He practised in front of a mirror and then in front of two friends."}, {"id": "p3", "text": "Ahmed had always been afraid of speaking in public."}, {"id": "p4", "text": "When his manager asked him to give a presentation, he decided to prepare carefully."}]}'::jsonb, '{"order": ["p3", "p4", "p2", "p1"]}'::jsonb, 'Introduce Ahmed''s fear, then the task, the preparation and the result.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('1aed8461-7179-5e06-8bae-25be2ebac889', 'rwfib-0009', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "The museum is {{1}} visiting if you are interested in history. It has one of the {{2}} collections of old maps in the country.", "blanks": {"1": ["worthing", "worthy", "worth"], "2": ["largely", "large", "largest"]}}'::jsonb, '{"blanks": {"1": "worth", "2": "largest"}}'::jsonb, '"worth + -ing" is the fixed pattern. "one of the" is followed by a superlative: "largest".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('4f7dfffd-81be-57f7-9db5-7de2276c5c30', 'rfib-0009', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Online reviews can help shoppers {{1}} what to buy. However, some reviews are not {{2}} because they are written by the sellers themselves.", "word_bank": ["decide", "reliable", "expensive", "refuse"]}'::jsonb, '{"blanks": {"1": "decide", "2": "reliable"}}'::jsonb, 'Reviews help people decide; reviews written by sellers are not reliable.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3a488046-f650-5ee6-acb3-4a28647ebabe', 'rmcs-0010', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'advanced', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Cities are often several degrees warmer than the countryside around them, an effect known as the urban heat island. Dark roads and roofs absorb sunlight during the day and release the heat slowly at night, while the lack of trees means there is less shade and less cooling from plants. Planners increasingly respond by painting roofs in light colours and creating green spaces, measures that can lower local temperatures noticeably during heatwaves.", "question": "What is the main purpose of the text?"}'::jsonb, '{"correct": ["A"]}'::jsonb, 'The text first explains the causes of the urban heat island and then describes what planners do about it.', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
