insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e5198e55-e4f3-5d47-a3a6-fcef455a2a28', '3a488046-f650-5ee6-acb3-4a28647ebabe', 'B', 'To argue that cities should stop building roads', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('5d5a3440-a203-59d9-b957-1fce48edac0e', '3a488046-f650-5ee6-acb3-4a28647ebabe', 'C', 'To describe the history of heatwaves', false, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('2a9a38a5-fdd4-5fac-b507-95de7e24c4c5', '3a488046-f650-5ee6-acb3-4a28647ebabe', 'D', 'To compare city and countryside weather records', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('e7859d15-3e44-5851-a6ee-8e13c0ecdb6e', 'rmcm-0010', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'advanced', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Cities are often several degrees warmer than the countryside around them, an effect known as the urban heat island. Dark roads and roofs absorb sunlight during the day and release the heat slowly at night, while the lack of trees means there is less shade and less cooling from plants. Planners increasingly respond by painting roofs in light colours and creating green spaces, measures that can lower local temperatures noticeably during heatwaves.", "question": "According to the text, which factors make cities warmer?"}'::jsonb, '{"correct": ["B", "D"]}'::jsonb, 'Dark roads and roofs and the lack of trees are given as causes. Light roofs are a solution, and wind is not mentioned.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
