insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('544d033d-1cb4-5134-ae88-9e9ff5243c5f', 'e7859d15-3e44-5851-a6ee-8e13c0ecdb6e', 'D', 'Dark surfaces that absorb sunlight', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('84b2fa15-1b67-564c-9d89-db055e25a3e3', 'rop-0010', '5ac15d51-a221-51df-974a-eb625cc75827', 'advanced', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "As a result, people who multitask often take longer and make more mistakes than those who focus on one task."}, {"id": "p2", "text": "Many people assume that multitasking makes them more productive."}, {"id": "p3", "text": "Instead, it switches rapidly between them, and each switch costs time and attention."}, {"id": "p4", "text": "Research, however, suggests that the brain does not really do two demanding tasks at once."}]}'::jsonb, '{"order": ["p2", "p4", "p3", "p1"]}'::jsonb, 'The belief comes first, "however" introduces the research, "Instead" explains it, and "As a result" gives the consequence.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('914cfdeb-c454-5ad6-952b-0498223521af', 'rwfib-0010', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'advanced', 'Choose the word that fits each gap in the text.', '{"text": "The report {{1}} the need for better public transport. Its authors argue that investment would {{2}} congestion and pollution.", "blanks": {"1": ["highlights", "highlighting", "highlighted"], "2": ["reduce", "reduction", "reducing"]}}'::jsonb, '{"blanks": {"1": "highlights", "2": "reduce"}}'::jsonb, '"The report" needs a present simple verb: "highlights". After "would" we use the base form "reduce".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('485c7e01-af99-5142-bd27-5df2815006aa', 'rfib-0010', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'advanced', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "The experiment was {{1}} several times to make sure the results were {{2}}.", "word_bank": ["consistent", "repeated", "ignored", "accidental"]}'::jsonb, '{"blanks": {"1": "repeated", "2": "consistent"}}'::jsonb, 'Scientists repeat an experiment to check that the results are consistent.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('c52bb333-658b-50df-95f7-86e88ce66c91', 'rmcs-0011', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Sam works in a café from Monday to Friday. On Saturdays he plays football with his friends in the park, and on Sundays he visits his grandparents. He likes his job, but he says the weekend is the best part of the week.", "question": "What does Sam do on Sundays?"}'::jsonb, '{"correct": ["D"]}'::jsonb, '"on Sundays he visits his grandparents".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
