insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ae4adbbb-dd22-578e-9222-6fd6884b596e', 'rmcm-0011', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'beginner', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Sam works in a café from Monday to Friday. On Saturdays he plays football with his friends in the park, and on Sundays he visits his grandparents. He likes his job, but he says the weekend is the best part of the week.", "question": "Which sentences are true about Sam?"}'::jsonb, '{"correct": ["A", "C"]}'::jsonb, 'He works Monday to Friday and plays football on Saturdays. He likes his job.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
