insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('b1bff9ac-1f39-5b7a-846e-0508da99880a', 'rop-0011', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Because I was in a hurry, I didn''t have breakfast."}, {"id": "p2", "text": "In the end, I walked to work and arrived twenty minutes late."}, {"id": "p3", "text": "I woke up late this morning."}, {"id": "p4", "text": "I ran to the bus stop, but the bus had already left."}]}'::jsonb, '{"order": ["p3", "p1", "p4", "p2"]}'::jsonb, 'The story follows the order of events: waking up late, no breakfast, missing the bus, walking to work.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3a50f433-d63c-5fdc-a562-f5d556ade531', 'rwfib-0011', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "My sister {{1}} a nurse. She {{2}} at the city hospital.", "blanks": {"1": ["is", "are", "be"], "2": ["works", "working", "work"]}}'::jsonb, '{"blanks": {"1": "is", "2": "works"}}'::jsonb, '"My sister" is singular: "is" and "works".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('bce66c65-dd52-5b49-ac4b-e75d000caa6d', 'rfib-0011', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "I {{1}} get up at seven. Then I have a {{2}} and make breakfast.", "word_bank": ["never", "window", "usually", "shower"]}'::jsonb, '{"blanks": {"1": "usually", "2": "shower"}}'::jsonb, '"usually" fits a daily routine, and you "have a shower".', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('9ffc3527-7371-5568-820c-a98edf83f6ad', 'rmcs-0012', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "A recent survey asked teenagers how they read for pleasure. Over half said they read mainly on phones or tablets, but most still preferred paper books for long stories. Many said they found it easier to concentrate on paper, while screens were better for short articles and news.", "question": "What did most teenagers prefer for long stories?"}'::jsonb, '{"correct": ["C"]}'::jsonb, '"most still preferred paper books for long stories".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
