insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('18420864-c098-519c-92dd-504cae7b9e13', 'rmcm-0012', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "A recent survey asked teenagers how they read for pleasure. Over half said they read mainly on phones or tablets, but most still preferred paper books for long stories. Many said they found it easier to concentrate on paper, while screens were better for short articles and news.", "question": "Which statements match the survey results?"}'::jsonb, '{"correct": ["B", "C", "D"]}'::jsonb, 'Three results are stated; the text does not say teenagers never read.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
