insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('7f666049-c98c-5662-a299-fb4f6c039140', 'rop-0012', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "The company is therefore considering a free bus from the station."}, {"id": "p2", "text": "The new space is much larger and has a lot more natural light."}, {"id": "p3", "text": "However, it is further from the train station, so some staff now spend longer travelling."}, {"id": "p4", "text": "Our office moved to a new building last month."}]}'::jsonb, '{"order": ["p4", "p2", "p3", "p1"]}'::jsonb, 'Introduce the move, describe the good side, add the problem with "However" and end with the response "therefore".', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('14615bb6-7fd9-502a-ae85-787d83d42520', 'rwfib-0012', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "The film was so {{1}} that I watched it twice. My friends were {{2}} when I told them.", "blanks": {"1": ["interesting", "interested", "interest"], "2": ["surprise", "surprising", "surprised"]}}'::jsonb, '{"blanks": {"1": "interesting", "2": "surprised"}}'::jsonb, 'Things are "interesting" (-ing); people feel "surprised" (-ed).', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
