insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('fb6d61c8-19f9-5a7f-8da4-9c8740d09665', 'rmcs-0013', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'advanced', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Historians once believed that the printing press spread rapidly because books became cheaper. More recent studies suggest a more complex picture: printers settled first in trading cities, where merchants already needed written records and could afford to buy books. In smaller towns, demand grew far more slowly, and handwritten copies remained common for decades. The spread of printing, in other words, followed existing networks of trade and literacy.", "question": "What does the text suggest about the spread of printing?"}'::jsonb, '{"correct": ["A"]}'::jsonb, 'The last sentence sums up the argument: printing "followed existing networks of trade and literacy".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
