insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('73310191-dc24-57e8-b098-43acbf5d89bb', 'rmcm-0013', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'advanced', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Historians once believed that the printing press spread rapidly because books became cheaper. More recent studies suggest a more complex picture: printers settled first in trading cities, where merchants already needed written records and could afford to buy books. In smaller towns, demand grew far more slowly, and handwritten copies remained common for decades. The spread of printing, in other words, followed existing networks of trade and literacy.", "question": "Which statements are supported by the text?"}'::jsonb, '{"correct": ["A", "C", "D"]}'::jsonb, 'Handwritten copies "remained common for decades", so that option is wrong.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
