insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('5eead88c-6f55-5cc3-87da-13cfc981f2c7', 'rop-0013', '5ac15d51-a221-51df-974a-eb625cc75827', 'advanced', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Today, cafés still play a similar social role in many cities."}, {"id": "p2", "text": "Coffee was first drunk in the Middle East more than five hundred years ago."}, {"id": "p3", "text": "These coffee houses were sometimes called \"penny universities\", because for the price of a cup people could hear the latest news and ideas."}, {"id": "p4", "text": "From there, traders carried it to Europe, where coffee houses soon became popular meeting places."}]}'::jsonb, '{"order": ["p2", "p4", "p3", "p1"]}'::jsonb, 'Origin, spread to Europe, "These coffee houses" refers back, and "Today" ends the timeline.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3164a4de-3afc-5213-a627-ac9e3af0973b', 'rwfib-0013', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'advanced', 'Choose the word that fits each gap in the text.', '{"text": "Despite {{1}} little funding, the project was a success. The team attributed this to careful {{2}}.", "blanks": {"1": ["receiving", "received", "receive"], "2": ["planned", "planning", "plan"]}}'::jsonb, '{"blanks": {"1": "receiving", "2": "planning"}}'::jsonb, '"Despite" is followed by a noun or -ing form: "receiving". After "careful" we need a noun: "planning".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0bc6c0e1-c391-5edc-b26a-4d0c7ae5d55c', 'rfib-0013', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'advanced', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "The new policy has been widely {{1}} for failing to {{2}} the causes of the problem.", "word_bank": ["criticised", "address", "ignore", "celebrated"]}'::jsonb, '{"blanks": {"1": "criticised", "2": "address"}}'::jsonb, '"failing to" shows a negative view, so the policy was "criticised". You "address" a problem; "ignore" would contradict the criticism.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('8c75d951-5b6b-5973-b82e-cb8dce9836f8', 'rmcs-0014', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Dogs and cats are the most popular pets in many countries. Dogs need a walk every day, so they are good for people who like to be active. Cats are more independent and can stay alone for longer, so they often suit people who work long hours.", "question": "Who are cats good for, according to the text?"}'::jsonb, '{"correct": ["B"]}'::jsonb, 'Cats "often suit people who work long hours".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
