insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('137bd29f-6e8d-5a1a-8fda-3b1febf57c45', 'rop-0014', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "He went to the shop and bought a red mountain bike."}, {"id": "p2", "text": "After six months, he had enough money."}, {"id": "p3", "text": "He saved some money every week from his part-time job."}, {"id": "p4", "text": "Tom wanted to buy a new bike."}]}'::jsonb, '{"order": ["p4", "p3", "p2", "p1"]}'::jsonb, 'The goal, the saving, the time passing and the purchase.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
