insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('30b83067-2abe-5f35-a23c-bf9872caed1c', 'rmcs-0015', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Electric cars produce no exhaust fumes, which helps to improve air quality in cities. They are also cheaper to run than petrol cars, because electricity usually costs less than fuel. On the other hand, they are still expensive to buy, and in some areas there are not enough charging points for long journeys.", "question": "What is one disadvantage of electric cars mentioned in the text?"}'::jsonb, '{"correct": ["B"]}'::jsonb, 'The text says "in some areas there are not enough charging points for long journeys".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
