insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('805fb3f4-3afc-5510-8c0b-ad9d07d1f63a', 'rmcm-0015', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Electric cars produce no exhaust fumes, which helps to improve air quality in cities. They are also cheaper to run than petrol cars, because electricity usually costs less than fuel. On the other hand, they are still expensive to buy, and in some areas there are not enough charging points for long journeys.", "question": "Which advantages of electric cars does the text mention?"}'::jsonb, '{"correct": ["A", "C"]}'::jsonb, 'Cleaner air and cheaper running costs are advantages. They are "still expensive to buy".', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
