insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('cc4005d5-6fbd-5f91-a02f-4c092cd04c46', 'rop-0015', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Learning to drive can be stressful for many people."}, {"id": "p2", "text": "One way to reduce stress is to practise in quiet streets before driving in busy traffic."}, {"id": "p3", "text": "With enough practice, most learners become confident drivers."}, {"id": "p4", "text": "It also helps to take lessons with a patient, qualified instructor."}]}'::jsonb, '{"order": ["p1", "p2", "p4", "p3"]}'::jsonb, 'The problem first, then two pieces of advice ("One way", "It also helps"), then the result.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('42989bac-23fc-58e3-a262-84c81d0fb6c8', 'rwfib-0015', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "I''m looking forward {{1}} meeting you next week. Please let me know if you need {{2}} before then.", "blanks": {"1": ["at", "for", "to"], "2": ["everything", "anything", "nothing"]}}'::jsonb, '{"blanks": {"1": "to", "2": "anything"}}'::jsonb, 'The fixed phrase is "look forward to". "if you need anything" is the natural phrase; "nothing" and "everything" do not fit the meaning.', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('b9839960-9ae3-59bc-b8ca-e457fb4a27f4', 'rfib-0015', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "The restaurant is very {{1}}, so it''s a good idea to {{2}} a table in advance.", "word_bank": ["cook", "empty", "popular", "book"]}'::jsonb, '{"blanks": {"1": "popular", "2": "book"}}'::jsonb, 'A popular restaurant fills up, so you book in advance.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('9b1b02fa-ed70-5f0f-85ba-9bd6e150b602', 'rmcs-0016', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'advanced', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Tourism can bring considerable economic benefits to a region, creating jobs and supporting local businesses. Yet when visitor numbers grow too quickly, residents may face rising rents, crowded streets and damage to historic sites. Some popular destinations have therefore introduced visitor limits or tourist taxes, arguing that the income can be used to protect the very attractions that draw people there.", "question": "Why have some destinations introduced tourist taxes, according to the text?"}'::jsonb, '{"correct": ["C"]}'::jsonb, 'The text says the income "can be used to protect the very attractions that draw people there".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
