insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('7f10b1b6-f510-505d-affb-221751dd78dc', 'rmcm-0016', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'advanced', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Tourism can bring considerable economic benefits to a region, creating jobs and supporting local businesses. Yet when visitor numbers grow too quickly, residents may face rising rents, crowded streets and damage to historic sites. Some popular destinations have therefore introduced visitor limits or tourist taxes, arguing that the income can be used to protect the very attractions that draw people there.", "question": "Which problems linked to rapid tourism growth are mentioned?"}'::jsonb, '{"correct": ["A", "C", "D"]}'::jsonb, 'Rents, crowds and damage are mentioned. Tourism creates jobs rather than reducing them.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
