insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('3f6250b9-98b3-5407-b134-c0d6c73bc793', '7f10b1b6-f510-505d-affb-221751dd78dc', 'D', 'Rising rents', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('1006dee2-5bd0-5932-8390-767ac49255a3', 'rop-0016', '5ac15d51-a221-51df-974a-eb625cc75827', 'advanced', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "The arrival of the railway changed this, making long journeys faster and cheaper."}, {"id": "p2", "text": "This was the beginning of mass tourism as we know it today."}, {"id": "p3", "text": "Until the nineteenth century, most people never travelled far from where they were born."}, {"id": "p4", "text": "Soon, ordinary families could afford day trips to the seaside."}]}'::jsonb, '{"order": ["p3", "p1", "p4", "p2"]}'::jsonb, 'The situation before, the change ("changed this"), its effect ("Soon") and the conclusion ("This was the beginning").', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('95603d14-4aa9-5627-91a8-ac9f614938b9', 'rwfib-0016', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'advanced', 'Choose the word that fits each gap in the text.', '{"text": "The findings {{1}} that the treatment is effective. Nevertheless, further research is {{2}} before it can be widely used.", "blanks": {"1": ["indication", "indicate", "indicating"], "2": ["require", "requiring", "required"]}}'::jsonb, '{"blanks": {"1": "indicate", "2": "required"}}'::jsonb, 'The subject "The findings" needs a verb: "indicate". "is required" is passive.', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('216070bb-1ef8-57e4-b0c3-8d9c2a7ca857', 'rfib-0016', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'advanced', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Scientists {{1}} that sea levels will continue to rise, posing a serious {{2}} to coastal communities.", "word_bank": ["predict", "threat", "remember", "benefit"]}'::jsonb, '{"blanks": {"1": "predict", "2": "threat"}}'::jsonb, '"will continue" refers to the future, so scientists "predict". A rise in sea level is a "threat", not a benefit.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('bbc43628-bc0b-519f-8114-a9ffb75c7718', 'rmcs-0017', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Lena is eight years old. She goes to school by bike with her father. Her favourite subject is art, because she loves drawing animals. After school, she has lunch at home and then plays with her little brother.", "question": "Why does Lena like art?"}'::jsonb, '{"correct": ["D"]}'::jsonb, '"because she loves drawing animals".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
