insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('a8338798-1bed-5114-90a6-c9c1969f7064', 'rmcm-0017', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'beginner', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Lena is eight years old. She goes to school by bike with her father. Her favourite subject is art, because she loves drawing animals. After school, she has lunch at home and then plays with her little brother.", "question": "Which sentences are true about Lena?"}'::jsonb, '{"correct": ["A", "D"]}'::jsonb, 'She cycles and is eight. She eats at home and has a brother.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
