insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('5c8d3d8b-e6ad-5cd4-92b8-45f61f43ffce', 'rop-0017', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Yesterday was my mum''s birthday."}, {"id": "p2", "text": "She was very happy and said it was her best birthday."}, {"id": "p3", "text": "In the afternoon, we gave her the cake and some flowers."}, {"id": "p4", "text": "In the morning, my sister and I made her a cake."}]}'::jsonb, '{"order": ["p1", "p4", "p3", "p2"]}'::jsonb, 'Topic first, then morning, afternoon and her reaction.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('aad90f4d-9c79-5745-aadf-04fe9ed42e0b', 'rwfib-0017', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "There {{1}} a big tree in our garden. In summer, we {{2}} under it.", "blanks": {"1": ["is", "be", "are"], "2": ["sitting", "sits", "sit"]}}'::jsonb, '{"blanks": {"1": "is", "2": "sit"}}'::jsonb, '"a big tree" is singular: "There is". "we" takes "sit".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('335869b9-d056-5ecb-8228-fdd2c453964c', 'rfib-0017', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "I {{1}} in a small flat near the {{2}}.", "word_bank": ["eat", "sky", "station", "live"]}'::jsonb, '{"blanks": {"1": "live", "2": "station"}}'::jsonb, 'You live in a flat; a flat can be near a station.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('10ab22bd-911b-5229-bb76-f6d1bfabb636', 'rmcs-0018', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Online courses allow people to study at their own speed and from any place with an internet connection. This makes them popular with adults who work full time. However, completion rates are often low. Learners who join a study group or set a regular weekly schedule are much more likely to finish their course.", "question": "What helps learners finish online courses, according to the text?"}'::jsonb, '{"correct": ["C"]}'::jsonb, 'The last sentence names study groups and a regular schedule.', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
