insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('cfd6b8c2-2b55-5e96-a430-0c49fb540a9e', 'rop-0018', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Residents closed the road for the day and set up tables outside their houses."}, {"id": "p2", "text": "The event was such a success that it will now take place every year."}, {"id": "p3", "text": "Everyone brought food to share, and some neighbours played music."}, {"id": "p4", "text": "Our neighbourhood held its first street party last summer."}]}'::jsonb, '{"order": ["p4", "p1", "p3", "p2"]}'::jsonb, 'Introduce the event, describe the set-up and the activities, then the result.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('8b39b147-eab9-5e93-aa42-a0141810ac35', 'rwfib-0018', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "The hotel staff were very {{1}}. They {{2}} a great restaurant near the beach.", "blanks": {"1": ["helpful", "helpless", "help"], "2": ["recommending", "recommended", "recommend"]}}'::jsonb, '{"blanks": {"1": "helpful", "2": "recommended"}}'::jsonb, 'Staff who help are "helpful". The past simple fits the story: "recommended".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('da32df09-8ba5-52aa-9f99-7d83195d3983', 'rfib-0018', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Regular {{1}} can help you sleep better and feel more {{2}} during the day.", "word_bank": ["dinner", "exercise", "tired", "energetic"]}'::jsonb, '{"blanks": {"1": "exercise", "2": "energetic"}}'::jsonb, 'Exercise helps sleep; you feel energetic, not tired.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('defe10ae-a100-5bb9-a734-a1402fab7729', 'rmcs-0019', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'advanced', 'Read the text. Choose the one answer that the text supports.', '{"passage": "False information often spreads faster online than accurate reports. One explanation is that misleading stories tend to be surprising or emotional, which makes people more likely to share them. Studies have found that simply asking users to consider whether a headline is accurate before sharing it can reduce the spread of false stories, even without removing any content.", "question": "According to the text, what can reduce the spread of false stories?"}'::jsonb, '{"correct": ["A"]}'::jsonb, '"simply asking users to consider whether a headline is accurate before sharing it can reduce the spread".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
