insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('96df7d44-5457-57e0-b60a-8e5b3332bd72', 'rmcm-0019', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'advanced', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "False information often spreads faster online than accurate reports. One explanation is that misleading stories tend to be surprising or emotional, which makes people more likely to share them. Studies have found that simply asking users to consider whether a headline is accurate before sharing it can reduce the spread of false stories, even without removing any content.", "question": "Which statements are supported by the text?"}'::jsonb, '{"correct": ["A", "B", "D"]}'::jsonb, 'The method works "even without removing any content".', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
