insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('2126b3c8-36ca-550d-b74c-eea70300b4bd', 'rop-0019', '5ac15d51-a221-51df-974a-eb625cc75827', 'advanced', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "As global temperatures rise, many of them are shrinking at an increasing rate."}, {"id": "p2", "text": "In the long term, however, communities that depend on these rivers may face serious water shortages."}, {"id": "p3", "text": "Glaciers store about seventy per cent of the world''s fresh water."}, {"id": "p4", "text": "In the short term, this can actually increase the flow of rivers fed by melting ice."}]}'::jsonb, '{"order": ["p3", "p1", "p4", "p2"]}'::jsonb, 'A fact, the change, its short-term effect, then the contrasting long-term effect ("however").', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('38f995e0-5200-51ae-aa65-27b0d1d25805', 'rwfib-0019', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'advanced', 'Choose the word that fits each gap in the text.', '{"text": "Not only {{1}} the scheme reduce costs, but it also improved staff satisfaction. Its success has {{2}} other departments to adopt it.", "blanks": {"1": ["did", "done", "does"], "2": ["prompt", "prompting", "prompted"]}}'::jsonb, '{"blanks": {"1": "did", "2": "prompted"}}'::jsonb, 'After "Not only" at the start, we invert: "did the scheme reduce". "has" + past participle: "prompted".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('8569a74e-21a3-56a0-8873-152134fae0d4', 'rfib-0019', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'advanced', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "The museum''s collection was {{1}} over two centuries and now includes objects of great historical {{2}}.", "word_bank": ["abandoned", "weakness", "acquired", "significance"]}'::jsonb, '{"blanks": {"1": "acquired", "2": "significance"}}'::jsonb, 'Collections are acquired over time, and old objects can have historical significance.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0a4469a6-48e4-514e-8fe7-275d406c7000', 'rmcs-0020', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "The supermarket near my house is open every day from seven in the morning to ten at night. It is big and sells food, clothes and things for the house. On Fridays, fruit and vegetables are cheaper, so it is very busy.", "question": "Why is the supermarket busy on Fridays?"}'::jsonb, '{"correct": ["A"]}'::jsonb, '"On Fridays, fruit and vegetables are cheaper, so it is very busy".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
