insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('94429d90-1cf8-5658-8edd-ea946186bca5', 'rmcm-0020', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'beginner', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "The supermarket near my house is open every day from seven in the morning to ten at night. It is big and sells food, clothes and things for the house. On Fridays, fruit and vegetables are cheaper, so it is very busy.", "question": "What does the supermarket sell?"}'::jsonb, '{"correct": ["A", "C", "D"]}'::jsonb, 'It sells food, clothes and things for the house.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
