insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('a231e34b-ddad-5399-bcb0-ceb71ae2b6ae', 'rop-0020', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Max likes running after balls and playing with other dogs."}, {"id": "p2", "text": "Every morning, Jack takes Max for a walk in the park."}, {"id": "p3", "text": "After the walk, they both come home tired and happy."}, {"id": "p4", "text": "Jack has a new puppy called Max."}]}'::jsonb, '{"order": ["p4", "p2", "p1", "p3"]}'::jsonb, 'Introduce Max, then the walk, what Max does and the end of the walk.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d0575199-9a46-5a21-a3f1-9ccfb76d3915', 'rwfib-0020', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "I {{1}} like coffee. I {{2}} tea.", "blanks": {"1": ["not", "don''t", "doesn''t"], "2": ["prefer", "prefers", "preferring"]}}'::jsonb, '{"blanks": {"1": "don''t", "2": "prefer"}}'::jsonb, '"I" takes "don''t" and "prefer".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3fb86537-086b-5f80-ac0d-d554091dd092', 'rfib-0020', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "My father {{1}} dinner every evening. His {{2}} dish is chicken with rice.", "word_bank": ["favourite", "cooks", "worst", "sleeps"]}'::jsonb, '{"blanks": {"1": "cooks", "2": "favourite"}}'::jsonb, 'Your father cooks dinner; chicken with rice is his favourite dish.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('8a6ae47f-8be2-5a22-8c87-7cb745f4d977', 'rmcs-0021', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "More people in our city now cycle to work. The council has built new bike lanes that separate cyclists from cars, and accidents involving cyclists have fallen. Some shop owners worried that fewer parking spaces would mean fewer customers, but a study found that people who cycle actually visit local shops more often.", "question": "What did the study find?"}'::jsonb, '{"correct": ["D"]}'::jsonb, '"people who cycle actually visit local shops more often".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
