insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('9901f0e9-f440-5598-89d6-707522da7138', 'rmcm-0021', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "More people in our city now cycle to work. The council has built new bike lanes that separate cyclists from cars, and accidents involving cyclists have fallen. Some shop owners worried that fewer parking spaces would mean fewer customers, but a study found that people who cycle actually visit local shops more often.", "question": "Which statements are true according to the text?"}'::jsonb, '{"correct": ["B", "C", "D"]}'::jsonb, 'The text implies there are fewer parking spaces, not more.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
