insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('23524364-07d4-5be6-8d4b-3c317cdfc4be', 'rop-0021', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "There are new colleagues to meet, new systems to learn and new routines to follow."}, {"id": "p2", "text": "After a month or so, most people find that everything feels much more familiar."}, {"id": "p3", "text": "It helps to keep a notebook and write down important information."}, {"id": "p4", "text": "When you start a new job, the first few weeks can feel overwhelming."}]}'::jsonb, '{"order": ["p4", "p1", "p3", "p2"]}'::jsonb, 'The general feeling, the details of the challenge, advice ("It helps") and the outcome.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('43649d34-3fac-5995-b8de-fd7191731fe4', 'rwfib-0021', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "He apologised {{1}} being late. He said the traffic {{2}} been terrible.", "blanks": {"1": ["about", "for", "of"], "2": ["has", "have", "had"]}}'::jsonb, '{"blanks": {"1": "for", "2": "had"}}'::jsonb, '"apologise for" is the fixed pattern. In reported speech, "has been" becomes "had been".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('f6b1578a-792b-56ed-90c0-c21549809711', 'rfib-0021', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "The flight was {{1}} because of the storm, so we had to {{2}} another night in the hotel.", "word_bank": ["cancelled", "stay", "leave", "boarded"]}'::jsonb, '{"blanks": {"1": "cancelled", "2": "stay"}}'::jsonb, 'A storm causes cancellations; then you have to stay longer.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('e21f3bfc-1829-56e5-b4f8-a765576f27f6', 'rmcs-0022', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'advanced', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Biodiversity refers to the variety of living things in an area, from microorganisms to large mammals. Ecosystems with high biodiversity tend to be more resilient: if one species declines, others can often perform similar roles. Conversely, when an ecosystem depends on only a few species, the loss of one can trigger a chain of effects that is difficult to reverse.", "question": "Why are ecosystems with high biodiversity more resilient, according to the text?"}'::jsonb, '{"correct": ["C"]}'::jsonb, '"if one species declines, others can often perform similar roles".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
