insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('b02bac18-02d4-50d9-8c1b-f8f43a07b238', 'e21f3bfc-1829-56e5-b4f8-a765576f27f6', 'C', 'Other species can take over the roles of a declining one.', true, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('a5cd283c-6d98-569f-9f89-9fa3dc7147c0', 'e21f3bfc-1829-56e5-b4f8-a765576f27f6', 'D', 'They have fewer microorganisms.', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('2f4a0e8e-30c9-542d-993d-77977334ede6', 'rmcm-0022', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'advanced', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Biodiversity refers to the variety of living things in an area, from microorganisms to large mammals. Ecosystems with high biodiversity tend to be more resilient: if one species declines, others can often perform similar roles. Conversely, when an ecosystem depends on only a few species, the loss of one can trigger a chain of effects that is difficult to reverse.", "question": "Which ideas are expressed in the text?"}'::jsonb, '{"correct": ["A", "B", "C"]}'::jsonb, 'The text says such effects are "difficult to reverse".', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
