insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('6e31ddd3-ba3f-5eb2-9f6f-fc30ebd8e902', 'rop-0022', '5ac15d51-a221-51df-974a-eb625cc75827', 'advanced', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Nevertheless, scientists stress that high vaccination rates must be maintained to prevent outbreaks."}, {"id": "p2", "text": "They worked by training the body''s immune system to recognise a disease without causing serious illness."}, {"id": "p3", "text": "Since then, vaccination programmes have greatly reduced or even eliminated several deadly diseases."}, {"id": "p4", "text": "The first vaccines were developed more than two hundred years ago."}]}'::jsonb, '{"order": ["p4", "p2", "p3", "p1"]}'::jsonb, 'History, how vaccines work, their success ("Since then") and a caution ("Nevertheless").', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('768aa9c8-0936-5294-9068-cd605ec0a3dc', 'rwfib-0022', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'advanced', 'Choose the word that fits each gap in the text.', '{"text": "Had the warning been {{1}} earlier, fewer homes would have been damaged. The authorities have since {{2}} the delay.", "blanks": {"1": ["issue", "issued", "issuing"], "2": ["acknowledged", "acknowledging", "acknowledge"]}}'::jsonb, '{"blanks": {"1": "issued", "2": "acknowledged"}}'::jsonb, '"Had the warning been" needs a past participle: "issued". "have since" + past participle: "acknowledged".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('b8311066-48ea-505f-8518-7d91d674efee', 'rfib-0022', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'advanced', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Critics argue that the new tax will place a heavy {{1}} on small businesses, which are less able to {{2}} extra costs.", "word_bank": ["burden", "advantage", "absorb", "avoid"]}'::jsonb, '{"blanks": {"1": "burden", "2": "absorb"}}'::jsonb, 'A tax is a "burden"; small firms are less able to "absorb" costs.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('79706050-e1d6-5286-b0e1-0e58ede5730e', 'rmcs-0023', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "When the national museums stopped charging for entry, the number of visitors almost doubled within a year. Supporters said free entry made culture available to everyone, not just those who could afford a ticket. However, museums now rely more on donations and government funding, and some have had to reduce opening hours to save money.", "question": "What happened after the museums stopped charging?"}'::jsonb, '{"correct": ["D"]}'::jsonb, '"the number of visitors almost doubled within a year".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
