insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('f0d78a5d-b852-5b26-865f-061bf8bfa9e6', 'rmcm-0023', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "When the national museums stopped charging for entry, the number of visitors almost doubled within a year. Supporters said free entry made culture available to everyone, not just those who could afford a ticket. However, museums now rely more on donations and government funding, and some have had to reduce opening hours to save money.", "question": "Which effects of free entry does the text mention?"}'::jsonb, '{"correct": ["B", "C", "D"]}'::jsonb, 'School visits are not mentioned.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
