insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('10c37bbf-5ef4-54ef-ad11-10f51e712b33', 'rop-0023', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "The plan slowly increases the distance they run each week."}, {"id": "p2", "text": "Many people dream of running a marathon."}, {"id": "p3", "text": "By race day, their bodies are ready to cover the full forty-two kilometres."}, {"id": "p4", "text": "To prepare, beginners usually follow a training plan that lasts several months."}]}'::jsonb, '{"order": ["p2", "p4", "p1", "p3"]}'::jsonb, 'The dream, the plan, how it works and the result on race day.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('c95326e1-d9bd-5c8e-85c5-f8b81cd4142e', 'rwfib-0023', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "She is used to {{1}} at night. She has {{2}} a nurse for ten years.", "blanks": {"1": ["working", "work", "worked"], "2": ["be", "being", "been"]}}'::jsonb, '{"blanks": {"1": "working", "2": "been"}}'::jsonb, '"be used to" + -ing: "working". Present perfect: "has been".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('b021ebd7-7dcf-5b1d-9637-139b5aed8a9e', 'rfib-0023', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "You can {{1}} money by cooking at home instead of eating out every {{2}}.", "word_bank": ["minute", "night", "save", "spend"]}'::jsonb, '{"blanks": {"1": "save", "2": "night"}}'::jsonb, 'Cooking at home saves money; eating out every night is expensive.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0fd6e213-fe54-53ac-9c71-f2a45ba96a18', 'rmcs-0024', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "In my country, summer is hot and dry, and it hardly ever rains. Winter is cold, and sometimes it snows in the mountains. Spring is my favourite season, because the weather is warm and there are flowers everywhere.", "question": "Why is spring the writer''s favourite season?"}'::jsonb, '{"correct": ["C"]}'::jsonb, '"because the weather is warm and there are flowers everywhere".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
