insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('e10ccdf0-b29b-563e-84ed-1aafb3583ec0', 'rmcm-0024', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'beginner', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "In my country, summer is hot and dry, and it hardly ever rains. Winter is cold, and sometimes it snows in the mountains. Spring is my favourite season, because the weather is warm and there are flowers everywhere.", "question": "What does the writer say about the weather?"}'::jsonb, '{"correct": ["A", "B", "C"]}'::jsonb, 'In summer "it hardly ever rains".', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
