insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('32e2fe96-bf08-5ec2-9ce9-7253792e4e87', 'rop-0024', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "By Friday, she felt much more confident."}, {"id": "p2", "text": "On her first day, she met her manager and her new colleagues."}, {"id": "p3", "text": "Anna started a new job at a bank last week."}, {"id": "p4", "text": "They showed her how to use the computer system."}]}'::jsonb, '{"order": ["p3", "p2", "p4", "p1"]}'::jsonb, 'New job, first day, training and how she felt at the end of the week.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('cb9d2777-08fd-5fbe-a267-629a3488c68f', 'rwfib-0024', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "We {{1}} to the cinema last night. The film {{2}} very funny.", "blanks": {"1": ["go", "going", "went"], "2": ["is", "was", "were"]}}'::jsonb, '{"blanks": {"1": "went", "2": "was"}}'::jsonb, '"last night" needs the past simple: "went" and "was".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ae2a8d42-ffc0-5fb7-9375-fc0ed33601b1', 'rfib-0024', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Can you {{1}} the window? It''s very {{2}} in here.", "word_bank": ["open", "close", "cold", "hot"]}'::jsonb, '{"blanks": {"1": "open", "2": "hot"}}'::jsonb, 'When it''s hot, you open a window.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('8524d036-a344-542c-a263-d3d5b1726ee0', 'rmcs-0025', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Several companies have tested a four-day working week, with staff paid the same as before. In most trials, managers reported that productivity stayed the same or even improved, while workers said they felt less stressed. Critics point out, however, that the model may be harder to use in services such as hospitals, which need staff every day.", "question": "What concern do critics raise about the four-day week?"}'::jsonb, '{"correct": ["B"]}'::jsonb, 'Critics say it "may be harder to use in services such as hospitals".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
