insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ee0057d8-efe4-51fb-adfa-5dbb131aed74', 'rmcm-0025', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Several companies have tested a four-day working week, with staff paid the same as before. In most trials, managers reported that productivity stayed the same or even improved, while workers said they felt less stressed. Critics point out, however, that the model may be harder to use in services such as hospitals, which need staff every day.", "question": "What did the trials show?"}'::jsonb, '{"correct": ["A", "B"]}'::jsonb, 'Staff were "paid the same"; hospitals are only mentioned by critics.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
