insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('cf838074-cffd-5af4-aa70-ab74906ca95c', 'rop-0025', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Many students, however, stay up late revising the night before."}, {"id": "p2", "text": "Getting a good night''s sleep before an exam is important."}, {"id": "p3", "text": "This often leaves them tired and less able to remember what they have studied."}, {"id": "p4", "text": "A better strategy is to revise over several weeks and rest well before the exam."}]}'::jsonb, '{"order": ["p2", "p1", "p3", "p4"]}'::jsonb, 'The idea, the common habit ("however"), its effect ("This") and a better approach.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('86827eff-f456-5975-800b-dbf230beb06b', 'rwfib-0025', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "If I {{1}} more free time, I would learn to play the guitar. I''ve always {{2}} to play an instrument.", "blanks": {"1": ["have", "had", "has"], "2": ["want", "wanted", "wanting"]}}'::jsonb, '{"blanks": {"1": "had", "2": "wanted"}}'::jsonb, 'Second conditional: "If I had ..., I would ...". "have always" + past participle: "wanted".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
