insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('7ea08faa-0c99-5e9c-ae3b-39f783d6dbbd', 'rmcs-0026', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'advanced', 'Read the text. Choose the one answer that the text supports.', '{"passage": "In many developed countries, the proportion of people over sixty-five is rising steadily, largely because of longer life expectancy and lower birth rates. This shift places pressure on pension systems and health services, as fewer working-age people support a growing number of retirees. Some economists argue, however, that the challenge is often overstated, since older people increasingly remain in work and contribute through volunteering and caring for family members.", "question": "What is the economists'' view mentioned at the end of the text?"}'::jsonb, '{"correct": ["C"]}'::jsonb, 'They "argue ... that the challenge is often overstated".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
