insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('fb353332-571a-5953-b7aa-ebe8317583b4', 'rmcm-0026', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'advanced', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "In many developed countries, the proportion of people over sixty-five is rising steadily, largely because of longer life expectancy and lower birth rates. This shift places pressure on pension systems and health services, as fewer working-age people support a growing number of retirees. Some economists argue, however, that the challenge is often overstated, since older people increasingly remain in work and contribute through volunteering and caring for family members.", "question": "Which causes of an ageing population does the text give?"}'::jsonb, '{"correct": ["A", "D"]}'::jsonb, 'Only life expectancy and birth rates are named as causes.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
