insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('5296a924-351c-5b38-9eee-af506f57ceda', 'rop-0026', '5ac15d51-a221-51df-974a-eb625cc75827', 'advanced', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "This method worked well on clear nights but was useless in cloudy weather."}, {"id": "p2", "text": "For centuries, sailors relied on the stars to find their way at sea."}, {"id": "p3", "text": "Today, satellite navigation allows ships to know their exact position at any time."}, {"id": "p4", "text": "The invention of the magnetic compass solved part of this problem."}]}'::jsonb, '{"order": ["p2", "p1", "p4", "p3"]}'::jsonb, 'The early method, its weakness ("This method"), a partial solution and the modern situation.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0a1f25a2-3223-5921-aa7e-bcbca628a197', 'rwfib-0026', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'advanced', 'Choose the word that fits each gap in the text.', '{"text": "The proposal was rejected on the {{1}} that it was too expensive. Its supporters, {{2}}, intend to submit a revised version.", "blanks": {"1": ["grounding", "grounds", "ground"], "2": ["despite", "although", "however"]}}'::jsonb, '{"blanks": {"1": "grounds", "2": "however"}}'::jsonb, '"on the grounds that" is a fixed phrase. "however" can sit between commas; "although" and "despite" cannot.', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('67f3a374-6b93-5fb2-8dea-8e4c13f8f71f', 'rfib-0026', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'advanced', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Although the treatment showed {{1}} results in early trials, its long-term {{2}} remain unknown.", "word_bank": ["causes", "promising", "disappointing", "effects"]}'::jsonb, '{"blanks": {"1": "promising", "2": "effects"}}'::jsonb, '"Although" contrasts good early results with unknown long-term effects.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('97153b80-eb4c-5a53-b7e1-4fbad176ee46', 'rmcs-0027', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Lucas lives in a small town. There is no train station, so he goes to the city by bus. The journey takes forty minutes. He reads a book or listens to music on the bus.", "question": "Why does Lucas take the bus to the city?"}'::jsonb, '{"correct": ["A"]}'::jsonb, '"There is no train station, so he goes to the city by bus".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
