insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('c724032c-5637-5bb8-9821-55db8d7fcf2d', 'rop-0027', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "When it was ready, she decorated it with chocolate."}, {"id": "p2", "text": "Sara wanted to make a cake for her friend''s party."}, {"id": "p3", "text": "First, she went to the shop to buy eggs, flour and sugar."}, {"id": "p4", "text": "Then she mixed everything together and put the cake in the oven."}]}'::jsonb, '{"order": ["p2", "p3", "p4", "p1"]}'::jsonb, 'The plan, the shopping, the baking and the decoration.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('c11516eb-d8fd-5bdd-a6e3-3257ebdb375b', 'rwfib-0027', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "My parents {{1}} a small shop. They {{2}} it every day at eight.", "blanks": {"1": ["has", "have", "having"], "2": ["opened", "open", "opens"]}}'::jsonb, '{"blanks": {"1": "have", "2": "open"}}'::jsonb, '"My parents" is plural: "have" and "open".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d3047997-cd54-54ce-a3fe-6a50c9a2ed9f', 'rfib-0027', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "It''s late. I''m very {{1}}, so I''m going to {{2}}.", "word_bank": ["tired", "bed", "school", "hungry"]}'::jsonb, '{"blanks": {"1": "tired", "2": "bed"}}'::jsonb, 'Tired people go to bed.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('b1f472dd-93de-5821-a658-bfbfe97f5d07', 'rmcs-0028', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Fast fashion brands produce new clothing collections every few weeks at low prices. This allows shoppers to follow trends cheaply, but it also encourages people to buy more and throw clothes away sooner. Making clothes uses large amounts of water and energy, so some shoppers now prefer second-hand shops or rent clothes for special occasions.", "question": "Why do some shoppers prefer second-hand shops or renting clothes?"}'::jsonb, '{"correct": ["C"]}'::jsonb, 'The text links the shift to the water and energy used to make clothes ("so some shoppers now prefer ...").', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
