insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3d18dcb3-2da8-5bf6-bab3-f1ffb7f9bfb7', 'rmcm-0028', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Fast fashion brands produce new clothing collections every few weeks at low prices. This allows shoppers to follow trends cheaply, but it also encourages people to buy more and throw clothes away sooner. Making clothes uses large amounts of water and energy, so some shoppers now prefer second-hand shops or rent clothes for special occasions.", "question": "What does the text say about fast fashion?"}'::jsonb, '{"correct": ["A", "C", "D"]}'::jsonb, 'It leads people to throw clothes away "sooner".', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
