insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ffadccfe-3234-5ad6-bc0a-c4cab5712f1b', 'rop-0028', '5ac15d51-a221-51df-974a-eb625cc75827', 'intermediate', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Our town''s old cinema closed ten years ago."}, {"id": "p2", "text": "Last year, a group of residents raised money to repair it."}, {"id": "p3", "text": "It reopened this spring as a community arts centre."}, {"id": "p4", "text": "For a long time, the building stood empty and began to fall apart."}]}'::jsonb, '{"order": ["p1", "p4", "p2", "p3"]}'::jsonb, 'The closure, the empty years, the fundraising and the reopening.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('ec67f851-19b7-56ce-8363-654699f6ed74', 'rwfib-0028', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'intermediate', 'Choose the word that fits each gap in the text.', '{"text": "The tickets sold out so {{1}} that many fans were disappointed. The organisers are {{2}} to add an extra show.", "blanks": {"1": ["quickly", "quicker", "quick"], "2": ["planned", "plan", "planning"]}}'::jsonb, '{"blanks": {"1": "quickly", "2": "planning"}}'::jsonb, 'An adverb describes how they sold: "quickly". "are" + -ing: "planning".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('a9582d76-8aca-504f-b437-e8fed94467cb', 'rfib-0028', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'intermediate', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Please keep your {{1}} with you at all times and report any {{2}} items to staff.", "word_bank": ["friendly", "luggage", "breakfast", "suspicious"]}'::jsonb, '{"blanks": {"1": "luggage", "2": "suspicious"}}'::jsonb, 'At a station you keep your luggage with you and report suspicious items.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('c34f08a9-f9d8-5da3-b9e0-3618308a8555', 'rmcs-0029', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'advanced', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Automation has transformed manufacturing, with machines now performing many tasks once done by hand. Contrary to some predictions, overall employment has not collapsed; instead, the nature of work has shifted. Routine jobs have declined, while demand has grown for roles requiring problem-solving, communication and technical maintenance. The central policy challenge, therefore, is ensuring that workers can retrain for these new roles.", "question": "According to the text, what is the central policy challenge?"}'::jsonb, '{"correct": ["D"]}'::jsonb, '"The central policy challenge, therefore, is ensuring that workers can retrain".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
