insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('62448b63-b643-5707-adad-7990742a553a', 'rmcm-0029', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'advanced', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Automation has transformed manufacturing, with machines now performing many tasks once done by hand. Contrary to some predictions, overall employment has not collapsed; instead, the nature of work has shifted. Routine jobs have declined, while demand has grown for roles requiring problem-solving, communication and technical maintenance. The central policy challenge, therefore, is ensuring that workers can retrain for these new roles.", "question": "Which statements are supported by the text?"}'::jsonb, '{"correct": ["A", "B", "D"]}'::jsonb, 'Machines perform "many tasks", not all.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
